/** Effects valid in: country, fleet. */
export interface EffectsInCountryFleet {
  /**
   * Iterate through each ship in the fleet or controlled by the country - executes the enclosed effects on all of them for which the limit triggers return true
   * ```
   * every_controlled_ship = { limit = { <triggers> } <effects> }
   * ```
   */
  everyControlledShip(args: { limit?: Trigger<"ship"> }, body: (scope: ShipScope) => void): void;

  /**
   * Iterate through each ship in the fleet or controlled by the country - executes the enclosed effects on all of them for which the limit triggers return true
   * ```
   * every_owned_ship = { limit = { <triggers> } <effects> }
   * ```
   */
  everyOwnedShip(args: { limit?: Trigger<"ship"> }, body: (scope: ShipScope) => void): void;

  /**
   * Iterate through each ship in the fleet or controlled by the country - executes the enclosed effects on one of them for which the limit triggers return true. Picks the specific object according to the order specified (position 0, order_by = trigger:num_pops would run the effects on the X with the most pops)
   * ```
   * ordered_controlled_ship = {
   * 	limit = { <triggers> }
   * 	position = <integer, starting with 0>
   * 	order_by = <variable>/trigger:<trigger>
   * 	inverse = yes/no (default: no - if yes, then 0 is lowest rather than highest)
   * 	<effects>
   * }
   * ```
   */
  orderedControlledShip(
    args: { position: number; orderBy: ScriptValue; inverse?: boolean; limit?: Trigger<"ship"> },
    body: (scope: ShipScope) => void
  ): void;

  /**
   * Iterate through each ship in the fleet or controlled by the country - executes the enclosed effects on one of them for which the limit triggers return true. Picks the specific object according to the order specified (position 0, order_by = trigger:num_pops would run the effects on the X with the most pops)
   * ```
   * ordered_owned_ship = {
   * 	limit = { <triggers> }
   * 	position = <integer, starting with 0>
   * 	order_by = <variable>/trigger:<trigger>
   * 	inverse = yes/no (default: no - if yes, then 0 is lowest rather than highest)
   * 	<effects>
   * }
   * ```
   */
  orderedOwnedShip(
    args: { position?: number; orderBy?: ScriptValue; inverse?: boolean; limit?: Trigger<"ship"> },
    body: (scope: ShipScope) => void
  ): void;

  /**
   * Iterate through each ship in the fleet or controlled by the country - executes the enclosed effects on one of them for which the limit triggers return true. Picks the specific object randomly.
   * ```
   * random_controlled_ship = {
   * 	limit = { <triggers> }
   * 	weights = { (optional - adds weights to affect the chance a specific object is selected)
   * 		base = float
   * 		modifier = { <add/factor = float> <triggers> }
   * 	}
   * 	<effects>
   * }
   * ```
   */
  randomControlledShip(
    args: { limit?: Trigger<"ship">; weights?: readonly Modifier<"ship">[] },
    body: (scope: ShipScope) => void
  ): void;

  /**
   * Iterate through each ship in the fleet or controlled by the country - executes the enclosed effects on one of them for which the limit triggers return true. Picks the specific object randomly.
   * ```
   * random_owned_ship = {
   * 	limit = { <triggers> }
   * 	weights = { (optional - adds weights to affect the chance a specific object is selected)
   * 		base = float
   * 		modifier = { <add/factor = float> <triggers> }
   * 	}
   * 	<effects>
   * }
   * ```
   */
  randomOwnedShip(
    args: { limit?: Trigger<"ship">; weights?: readonly Modifier<"ship">[] },
    body: (scope: ShipScope) => void
  ): void;

  /**
   * Sets the scoped fleet/country's aggro range in intra-system units
   * ```
   * set_aggro_range = <int>
   * ```
   */
  setAggroRange(value: ScriptValue): void;

  /**
   * Determines whether the scoped fleet/country's aggro range is measured from the fleet's current position or its spawn location
   * ```
   * set_aggro_range_measure_from = <key, self/return_point>
   * ```
   */
  setAggroRangeMeasureFrom(value: AggroRangeMeasureFrom): void;

  /**
   * Sets Space Fauna growth stance. Setting to 'none' resets stance to use default country policy. (controlled/excessive/none)
   * ```
   * set_fauna_fleet_growth_stance = <value> (controlled/excessive/none)
   * ```
   */
  setFaunaFleetGrowthStance(value: GrowthStance): void;
}

