  repairAmount(value: ScriptValue): void;

  /**
   * Restores a certain amount of armor points to the scoped ship or fleet
   * ```
   * repair_armor_amount = 10.0
   * ```
   */
  repairArmorAmount(value: ScriptValue): void;

