  /**
   * Sets scoped leader as non/recruitable
   * ```
   * recruitable = yes
   * ```
   */
  recruitable(value?: boolean): void;

  /**
   * Removes all negative traits from the scoped leader
   * ```
   * remove_all_negative_traits = yes
   * ```
   */
  removeAllNegativeTraits(value?: boolean): void;

  /**
   * Removes all non-negative traits from the scoped leader
   * ```
   * remove_all_positive_traits = yes
   * ```
   */
  removeAllPositiveTraits(value?: boolean): void;

  /**
   * Removes all traits from the scoped leader
   * ```
   * remove_all_traits = yes
   * ```
   */
