/** Effects valid in: pop_job. */
export interface EffectsInPopJob {
  /**
   * Iterate through each pop group that contains this job - executes the enclosed effects on all of them for which the limit triggers return true.
   * ```
   * every_job_pop_group = { limit = { <triggers> } <effects> }
   * ```
   */
  everyJobPopGroup(
    args: { limit?: Trigger<"pop_group"> },
    body: (scope: PopGroupScope) => void
  ): void;

  /**
   * Instantly destroys part of the assigned pops to this job
   * ```
   * kill_assigned_pop_amount = {
   * 	limit = { <triggers> }
   * 	amount = <amount killed> OR percentage = <percentage killed>
   * 	random = <number> (optional)
   * 	growth_category = <key> (optional, default: 'GROWTH_CAT_OTHER')
   * }
   * ```
   */
  killAssignedPopAmount(args: {
    limit?: Trigger<"pop_job">;
    amount?: ScriptValue;
    random?: ScriptValue;
    percentage?: ScriptValue;
    growthCategory?: string;
  }): void;

  /**
   * Iterate through each pop group that contains this job - executes the enclosed effects on one of them for which the limit triggers return true. Picks the specific object according to the order specified (position 0, order_by = trigger:num_pops would run the effects on the X with the most pops)
   * ```
   * ordered_job_pop_group = {
   * 	limit = { <triggers> }
   * 	position = <integer, starting with 0>
   * 	order_by = <variable>/trigger:<trigger>
   * 	inverse = yes/no (default: no - if yes, then 0 is lowest rather than highest)
   * 	<effects>
   * }
   * ```
   */
  orderedJobPopGroup(
    args: {
      position: number;
      orderBy: ScriptValue;
      inverse?: boolean;
      limit?: Trigger<"pop_group">;
    },
    body: (scope: PopGroupScope) => void
  ): void;

  /**
   * Iterate through each pop group that contains this job - executes the enclosed effects on one of them for which the limit triggers return true. Picks the specific object randomly.
   * ```
   * random_job_pop_group = {
   * 	limit = { <triggers> }
   * 	weights = { (optional - adds weights to affect the chance a specific object is selected)
   * 		base = float
   * 		modifier = { <add/factor = float> <triggers> }
   * 	}
   * 	<effects>
   * }
   * ```
   */
  randomJobPopGroup(
    args: { limit?: Trigger<"pop_group">; weights?: readonly Modifier<"pop_group">[] },
    body: (scope: PopGroupScope) => void
  ): void;

  /**
   * Instantly sacrifices part of the assigned pops to this job
   * ```
   * sacrifice_assigned_pop_amount = {
   * 	limit = { <triggers> }
   * 	amount = <amount sacrificed> OR percentage = <percentage sacrificed>
   * }
   * ```
   */
  sacrificeAssignedPopAmount(args: {
    limit?: Trigger<"pop_job">;
    amount?: ScriptValue;
    percentage?: ScriptValue;
  }): void;
}

